def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining_cap = bins - item
    return np.where(remaining_cap >= 0, -remaining_cap, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    indices = np.arange(len(bins))
    return np.where(bins >= item, -indices, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining_cap = bins - item
    target = item * 0.5
    return np.where(remaining_cap >= 0, - (remaining_cap - target) ** 2, -np.inf)
